const input = $input.first().json.body ?? $input.first().json;
const { headers } = $input.first().json;

let { access_token } = input;
const {
  schema, select, mutate, action,
  values, where, options, output, except
} = input;

if (output && except) {
  return {
    code: 400,
    message: 'Não use "output" e "except" juntos'
  };
}

// DETECTANDO CHAVE DE ACESSO
//
function getAccessTokenFromCookie(cookieHeader) {
  if (!cookieHeader) return null;

  const cookies = cookieHeader.split(";").reduce((acc, cookie) => {
    const [name, value] = cookie.trim().split("=");
    acc[name] = value;
    return acc;
  }, {});

  return cookies["authorization"] || cookies["access_token"] || null;
}
// 1. Checa no payload diretamente
if (input.authorization || input.access_token) {
  access_token = input.authorization ?? input.access_token;
}
// 2. Tenta pegar do header Authorization
else if (headers?.authorization) {
  access_token = headers.authorization;
}
// 3. Tenta pegar dos cookies
else if (headers?.cookie) {
  access_token = getAccessTokenFromCookie(headers.cookie);
}

if (!access_token) {
  return {
    code: 401,
    message: 'Usuário não autenticado'
  };
}


// DETECTANDO PARAMETROS DE AUTORIZACAO
//
const operation = select ? 'select' : mutate ? 'mutate' : null;
const entity = select ?? mutate;

if (!operation) {
  return {
    code: 400,
    message: 'Requisição deve conter "select" ou "mutate"'
  }
}

return {
  access_token,
  payload: {
    schema, operation, entity, action,
    values, where, options, output, except
  }
};

const json = $input.first().json;

if (json.error) {
  return { code: 500, message: json.error };
}
if (json.message) {
  return { code: 200, message: json.message, data: [] };
}

const jsonResult = json[Object.keys(json)[0]];

let status;

if (jsonResult.trim().startsWith('{')) {
  try {
    status = JSON.parse(jsonResult);
    if (status.code) {
      return status;
    }
  } catch { } // podemos ignorar. não veio o json.
}

return {
  code: 500,
  message: 'A consulta não produziu o resultado esperado',
  data: [ status ]
}

const parametros = $('Parâmetros de Requisição').first().json;
const payload = $input.first().json;

const data = payload?.data;
let output = parametros.payload?.output;
let except = parametros.payload?.except;

function filterByProjection(dataArray, inclusions, exclusions) {
  return dataArray.map(obj => filterObject(obj, inclusions, exclusions));
}

function filterObject(obj, inclusions, exclusions) {
  const result = JSON.parse(JSON.stringify(obj)); // deep clone

  // Se tem output (whitelist): remove tudo que NÃO está na lista
  if (inclusions && inclusions.length > 0) {
    removePropertiesNotIn(result, inclusions);
    return result;
  }

  // Se tem except (blacklist): remove tudo que ESTÁ na lista
  if (exclusions && exclusions.length > 0) {
    removePropertiesIn(result, exclusions);
    return result;
  }

  return result;
}

function removePropertiesNotIn(obj, inclusions) {
  // Agrupa por nível: { "": ["id", "nome"], "papeis": ["nome", "codigo"] }
  const pathsByLevel = {};

  inclusions.forEach(path => {
    const keys = path.split('.');
    if (keys.length === 1) {
      if (!pathsByLevel[""]) pathsByLevel[""] = [];
      pathsByLevel[""].push(keys[0]);
    } else {
      const parent = keys[0];
      const child = keys.slice(1).join('.');
      if (!pathsByLevel[parent]) pathsByLevel[parent] = [];
      pathsByLevel[parent].push(child);
    }
  });

  // Remove propriedades do nível raiz
  if (pathsByLevel[""]) {
    const allowedKeys = pathsByLevel[""];
    Object.keys(obj).forEach(key => {
      if (!allowedKeys.includes(key) && !pathsByLevel[key]) {
        delete obj[key];
      }
    });
  } else {
    // Se não tem propriedades raiz permitidas, remove tudo exceto os pais com filhos
    Object.keys(obj).forEach(key => {
      if (!pathsByLevel[key]) {
        delete obj[key];
      }
    });
  }

  // Processa propriedades aninhadas
  Object.keys(pathsByLevel).forEach(parentKey => {
    if (parentKey === "") return;

    const childPaths = pathsByLevel[parentKey];
    const parentValue = obj[parentKey];

    if (Array.isArray(parentValue)) {
      parentValue.forEach(item => {
        if (item && typeof item === 'object') {
          removePropertiesNotIn(item, childPaths);
        }
      });
    } else if (parentValue && typeof parentValue === 'object') {
      removePropertiesNotIn(parentValue, childPaths);
    }
  });
}

function removePropertiesIn(obj, exclusions) {
  exclusions.forEach(path => {
    const keys = path.split('.');
    deleteNestedProperty(obj, keys);
  });
}

function deleteNestedProperty(obj, keys) {
  if (keys.length === 1) {
    delete obj[keys[0]];
    return;
  }

  const [firstKey, ...restKeys] = keys;
  const current = obj[firstKey];

  if (current === null || current === undefined) return;

  if (Array.isArray(current)) {
    current.forEach(item => {
      if (item && typeof item === 'object') {
        deleteNestedProperty(item, restKeys);
      }
    });
  } else if (typeof current === 'object') {
    deleteNestedProperty(current, restKeys);
  }
}

try {
  const projection = filterByProjection(data, output, except);
  payload.data = projection;
} catch (error) {
  console.log(error);
}

return payload;

